@RestController
@RequestMapping("/api/v1/users")
public class UserController {

    // Path Variable + Request Parameter Binding
    @GetMapping("/{tenantId}/search")
    public ResponseEntity<List<UserDto>> searchUsers(
            @PathVariable("tenantId") UUID tenantId,
            @RequestParam(name = "q", defaultValue = "") String query,
            @RequestParam(name = "limit", defaultValue = "20") int limit) {
        List<UserDto> users = userService.search(tenantId, query, limit);
        return ResponseEntity.ok(users);
    }

    // Request Body Binding
    @PostMapping
    public ResponseEntity<UserDto> createUser(
            @PathVariable("tenantId") UUID tenantId,
            @Valid @RequestBody CreateUserCommand command) {
        UserDto created = userService.create(tenantId, command);
        return ResponseEntity.status(HttpStatus.CREATED).body(created);
    }
}
